from collections import Counter

class Solution:
    def leastBricks(self, wall: list[list[int]]) -> int:
        edge_count = Counter()
        for row in wall:
            pos = 0
            for brick in row[:-1]:
                pos += brick
                edge_count[pos] += 1
        return len(wall) - (max(edge_count.values()) if edge_count else 0)

